symbolsHeader = symbolMapping(bitsHeader, 2, "psk");
sHeader       = pulseShaping(symbolsHeader, sps);
xHeader       = iqModulation(sHeader, fc, Fs);

%% Pilot generation (for channel estimation and equalization)
bitsPilot    = bits(1 : nPilotSymbols * log2(M));
symbolsPilot = symbolMapping(bitsPilot, M, modScheme, symOrder);

%% Data generation (to calculate BER, SER, EVM)
bitsData    = bits(1 : nDataSymbols * log2(M));
symbolsData = symbolMapping(bitsData, M, modScheme, symOrder);

%% Noise Filtering
% Module 6.
yFiltered = yDSO;

%% Frame synchronization
nHeaderSamples = numel(xHeader);
nPilotSamples  = (nPilotSymbols + 10) * sps;
nDataSamples   = (nDataSymbols + 10) * sps;
nFrameSamples  = nHeaderSamples + nPilotSamples + nDataSamples;

yFrame = frameSynchronization(yFiltered, xHeader, nFrameSamples);

%% IQ demodulation (downconversion)
rFrame = iqDemodulation(yFrame, fc, Fs, Rs);

%% Carrier Phase Correction (header-based, static phase only)
rHeader  = rFrame(1:nHeaderSamples);                      % baseband header
symbolsHeaderRx = correlationReceiver(rHeader, sps, numel(symbolsHeader)); % Header baseband demodulation (received header symbols)
phi = angle(sum(symbolsHeaderRx .* conj(symbolsHeader))); % Phase of zero-lag complex correlation
rFrame = rFrame * exp(-1j*phi);                           % derotate whole frame
fprintf("Phase estimate = %.1f deg\n", rad2deg(phi));

%% Pilot and data extraction
rPilot = rFrame(nHeaderSamples + (1 : nPilotSamples));
rData  = rFrame(nHeaderSamples + nPilotSamples + (1 : nDataSamples));

%% Correlation receiver (baseband demodulation)
symbolsPilotReceived = correlationReceiver(rPilot, sps, nPilotSymbols);
symbolsDataReceived  = correlationReceiver(rData, sps, nDataSymbols);

%% Equalization
% Module 6.

%% Symbol demapping
bitsReceived = symbolDemapping(symbolsDataReceived, M, modScheme, symOrder);

%% Calculations
% Bit Error Rate (BER)
ber = mean(bitsData ~= bitsReceived);
fprintf("BER = %.3e\n", ber);

% Symbol Error Rate (SER)
errorSymbols = bit2int(bitsData, log2(M)) ~= bit2int(bitsReceived, log2(M));
ser = mean(errorSymbols);
fprintf("SER = %.2e\n", ser);

